-- name: ListLatestFinishedJobs :many
SELECT t2.id, t2.status, t2.finished_at
FROM (
    SELECT t1.id AS id, t1.status AS status, t1.finished_at AS finished_at
    FROM jobs AS t1
    WHERE (t1.job_type = sqlc.arg(job_type)::text)
      AND ((sqlc.narg(status)::int4 IS NULL) OR (t1.status = sqlc.narg(status)::int4))
      AND (NOT (t1.finished_at IS NULL))
) AS t2
ORDER BY t2.finished_at DESC, t2.id DESC
LIMIT 2;
